  const cleanSender = senderPn.replace(/\D/g, '');
  // [AJUSTE] Limpa o remoteJidAlt
  const cleanRemoteAlt = remoteJidAlt.replace(/\D/g, '');

  let telefoneCorrigido = '';

  // REGRA DE OURO (Atualizada):
  // 1. Tentar usar o senderPn.
  if (cleanSender.length >= 10) {
    telefoneCorrigido = cleanSender;
  } 

  // 2. Tentar usar o remoteJidAlt (caso de LID, como no seu teste).
  // [AJUSTE] Adicionado este bloco else if
  else if (cleanRemoteAlt.length >= 10 && remoteJidAlt.endsWith('@s.whatsapp.net')) {
    telefoneCorrigido = cleanRemoteAlt;
  }

  // 3. Se não houver, checar se o remoteJid é um JID de usuário (DM padrão).
  else if (remoteJid.endsWith('@s.whatsapp.net')) {
    telefoneCorrigido = cleanRemote;
  }

  // 3. Padroniza para E.164 Brasil
  if (telefoneCorrigido && !telefoneCorrigido.startsWith('55')) {
    telefoneCorrigido = '55' + telefoneCorrigido;
  }

  // 4. Sobrescreve o remoteJid SEMPRE com o JID
  if (telefoneCorrigido) {
    key.remoteJid = telefoneCorrigido + '@s.whatsapp.net';
  }

  return {
    json
  };
});

