}
let finalResponse = String(rawOutput);

// 2. Limpeza Inicial
const thinkingRegex = new RegExp('<thinking>[\\s\\S]*?<\\/thinking>', 'gm');
finalResponse = finalResponse.replace(thinkingRegex, "").trim();

if (finalResponse.startsWith('===')) {
  finalResponse = finalResponse.substring(3).trim();
}

// 3. Extração Segura do JSON (Contorno do Bug do n8n)
let extractedData = null;

// Construímos os caracteres '```' via ASCII para o n8n não dar crash
const bt3 = String.fromCharCode(96) + String.fromCharCode(96) + String.fromCharCode(96);
const jsonMarkdownRegex = new RegExp(bt3 + '(?:json)?\\s*(\\{[\\s\\S]*?\\})\\s*' + bt3, 'i');

let match = finalResponse.match(jsonMarkdownRegex);

if (match) {
    try {
        extractedData = JSON.parse(match[1]); 
        finalResponse = finalResponse.replace(match[0], '').trim(); 
    } catch (e) {
        // Ignora erro de conversão
    }
} else {
    // Fallback: Busca via índices '{' e '}' caso não tenha o markdown
    const firstBrace = finalResponse.indexOf('{');
    const lastBrace = finalResponse.lastIndexOf('}');

    if (firstBrace !== -1 && lastBrace !== -1 && lastBrace > firstBrace) {
        const possibleJsonString = finalResponse.substring(firstBrace, lastBrace + 1);
        try {
            extractedData = JSON.parse(possibleJsonString);
            finalResponse = finalResponse.replace(possibleJsonString, '').trim(); 
            // Limpa as crases residuais se existirem
            finalResponse = finalResponse.replace(new RegExp(bt3 + 'json|' + bt3, 'g'), '').trim();
        } catch (e) { }
    }
}

// 4. Divisão de Mensagens (Chunking)
const partes = [];
if (finalResponse.length > 0) {
    const frases = finalResponse.match(/[^.!?]+[.!?]+/g) || [finalResponse];
    let buffer = "";

    for (const frase of frases) {
        if ((buffer + frase).length > 800) {
            if (buffer.trim()) partes.push(buffer.trim());
            buffer = frase; 
        } else {
            buffer += frase;
        }
    }
    if (buffer.trim()) partes.push(buffer.trim());
}

// 5. Retorno Estruturado
if (partes.length === 0) {
    if (extractedData) {
        return [{ 
            json: { 
                message: "Agradecemos as informações. O seu perfil será avaliado.", 
                telefone: telefoneContato, // <-- Telefone adicionado aqui
                extracted_data: extractedData, 
