            } 
        }];
    }
    return [{ json: { message: "", telefone: telefoneContato, status_triagem: "andamento" } }]; // <-- E aqui
}

return partes.map((msg, index) => {
    const isLastMessage = index === partes.length - 1;
    return {
        json: {
            message: msg,
            telefone: telefoneContato, // <-- E aqui
            extracted_data: isLastMessage ? extractedData : null, 
            status_triagem: (isLastMessage && extractedData && extractedData.status_triagem) ? extractedData.status_triagem : "andamento"
        }
    };
});

